<template><div class="page"><div class="head"><div><h2>实时异常告警中心</h2><p>仅检测实时采集会话的数据，离线 CSV 与离线仿真结果不会进入本页面。</p></div><el-button @click="loadSessions">刷新会话</el-button></div><el-card><el-form inline><el-form-item label="实时采集会话"><el-select v-model="sessionId" filterable @change="selectSession"><el-option v-for="s in sessions" :key="s.id" :value="s.id" :label="`${s.name} / ${labels[s.state]} / ${s.sample_count} 条`"/></el-select></el-form-item><el-form-item label="实时检测"><el-switch v-model="enabled" :disabled="!sessionId" active-text="已启用" inactive-text="未启用" @change="changeMonitoring"/></el-form-item></el-form><el-alert v-if="!sessionId" title="请选择实时采集会话后启用异常检测" type="info" :closable="false"/><el-alert v-else-if="!enabled" title="当前会话尚未启用异常检测，实时数据会继续接收但不会生成告警" type="warning" :closable="false"/><el-alert v-else :title="state==='live'?'正在检测实时接入数据':'检测已启用，等待实时数据接入'" :type="state==='live'?'success':'info'" :closable="false"/></el-card><div class="stats"><el-card><small>会话状态</small><strong>{{labels[state]||'未选择'}}</strong></el-card><el-card><small>实时样本</small><strong>{{sampleCount}}</strong></el-card><el-card><small>告警数量</small><strong class="danger">{{alarms.length}}</strong></el-card><el-card><small>最新健康指数</small><strong>{{alarms[0]?.health_index??'—'}}</strong></el-card></div><el-card><template #header><b>实时告警记录</b></template><el-empty v-if="!alarms.length" description="暂无实时告警"/><el-table v-else :data="alarms" stripe><el-table-column prop="created_at" label="告警时间" width="190"><template #default="s">{{new Date(s.row.created_at).toLocaleString()}}</template></el-table-column><el-table-column prop="severity" label="等级" width="90"><template #default="s"><el-tag :type="s.row.severity==='critical'?'danger':'warning'">{{s.row.severity}}</el-tag></template></el-table-column><el-table-column prop="fault_name" label="诊断故障"/><el-table-column prop="signal" label="异常信号" width="120"/><el-table-column label="检测依据"><template #default="s">{{s.row.signal}}={{s.row.value}}，阈值 {{operators[s.row.operator]}}{{s.row.threshold}}</template></el-table-column><el-table-column prop="isolation_target" label="隔离对象"/><el-table-column prop="health_index" label="健康指数" width="100"/></el-table></el-card></div></template>
<script setup>import{ref,onMounted,onUnmounted}from'vue';import{ElMessage}from'element-plus';const LIVE_SOURCE_KEY='phm-live-source',sessions=ref([]),sessionId=ref(null),enabled=ref(false),state=ref(''),sampleCount=ref(0),alarms=ref([]),cursor=ref(0);const labels={waiting:'等待数据',live:'正在接收',stale:'接收中断',closed:'采集结束'},operators={gt:'>',gte:'≥',lt:'<',lte:'≤',eq:'='};let timer,generation=0;async function api(url,body){const token=document.cookie.split('; ').find(x=>x.startsWith('csrftoken='))?.slice(10);const r=await fetch(url,{credentials:'include',...(body!==undefined?{method:'POST',headers:{'Content-Type':'application/json',...(token?{'X-CSRFToken':decodeURIComponent(token)}:{})},body:JSON.stringify(body)}:{})});const j=await r.json();if(!r.ok)throw Error(j.detail||j.error);return j}async function loadSessions(){try{sessions.value=await api('/api/v1/phm/telemetry/sessions/')}catch(e){ElMessage.error(e.message)}}function selectSession(){generation++;clearTimeout(timer);cursor.value=0;alarms.value=[];const s=sessions.value.find(x=>x.id===sessionId.value);enabled.value=!!s?.monitoring_enabled;state.value=s?.state||'';sampleCount.value=s?.sample_count||0;localStorage.setItem(LIVE_SOURCE_KEY,JSON.stringify({id:sessionId.value,name:s?.name||''}));poll(generation)}async function changeMonitoring(value){try{const s=await api(`/api/v1/phm/telemetry/sessions/${sessionId.value}/monitoring/`,{enabled:value});enabled.value=s.monitoring_enabled;ElMessage.success(value?'实时异常检测已启用':'实时异常检测已停止')}catch(e){enabled.value=!value;ElMessage.error(e.message)}}async function poll(g){if(!sessionId.value)return;try{const j=await api(`/api/v1/phm/telemetry/sessions/${sessionId.value}/alarms/?after=${cursor.value}`);if(g!==generation)return;state.value=j.session.state;sampleCount.value=j.session.sample_count;enabled.value=j.session.monitoring_enabled;if(j.results.length){cursor.value=j.next_cursor;alarms.value=[...j.results.reverse(),...alarms.value].slice(0,500)}}catch(e){if(g===generation)ElMessage.error(e.message)}if(g===generation)timer=setTimeout(()=>poll(g),1000)}onMounted(async()=>{await loadSessions();const saved=JSON.parse(localStorage.getItem(LIVE_SOURCE_KEY)||'null');const found=saved&&sessions.value.find(s=>s.id===saved.id);if(found){sessionId.value=found.id;selectSession()}else if(sessions.value.length){sessionId.value=sessions.value[0].id;selectSession()}});onUnmounted(()=>{generation++;clearTimeout(timer)})</script>
<style scoped>.page{max-width:1400px}.head{display:flex;justify-content:space-between;align-items:start;margin-bottom:18px}.head p{color:#718198}.el-select{width:360px}.el-alert{margin-top:12px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:16px 0}.stats small,.stats strong{display:block}.stats strong{font-size:24px;margin-top:8px}.danger{color:#e34d59}@media(max-width:900px){.stats{grid-template-columns:repeat(2,1fr)}}</style>
